package com.nigson.commerce.cart;
import java.util.*;
import java.time.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.*;
import com.nigson.commerce.platform.AuditWriter;
import com.nigson.shared.problem.*;
/** Caller transactions preserve all-or-nothing checkout and verified financial truth. */
public final class JdbcCartCheckout implements CartCheckout {
 private final JdbcTemplate jdbc;private final CartRepository carts;private final Clock clock;private final AuditWriter audit;private final io.micrometer.core.instrument.MeterRegistry metrics;
 public JdbcCartCheckout(JdbcTemplate jdbc,CartRepository carts,Clock clock,AuditWriter audit,io.micrometer.core.instrument.MeterRegistry metrics){this.jdbc=jdbc;this.carts=carts;this.clock=clock;this.audit=audit;this.metrics=metrics;}
 private void transaction(){if(!TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("LOCAL_TRANSACTION_REQUIRED");}
 private Map<String,Object> order(UUID id,boolean lock){var rows=jdbc.queryForList("SELECT id,party_id,organization_id,market_id,cart_id,status,payment_status,currency_code,grand_total FROM commerce.sales_order WHERE id=?"+(lock?" FOR UPDATE":""),id);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);return rows.getFirst();}
 private CartValues.Cart context(Map<String,Object> order){if(order.get("cart_id")==null)throw CartValues.rule();var cart=carts.find((UUID)order.get("party_id"),(UUID)order.get("cart_id"),true);if(!cart.marketId().equals(order.get("market_id"))||!Objects.equals(cart.organizationId(),order.get("organization_id")))throw CartValues.rule();return cart;}
 private CartValues.Cart change(CartValues.Cart before,String state,UUID order,UUID correlation,AuditValues.Reason reason){if(before.version()==Long.MAX_VALUE)throw CartValues.rule();String subject="cart-checkout";jdbc.update("UPDATE commerce.cart SET status=?,converted_order_id=?,version=version+1,updated_at=?,updated_by=? WHERE id=?",state,order,java.sql.Timestamp.from(clock.instant()),subject,before.id());audit.append(subject,AuditValues.ActorKind.SYSTEM,AuditValues.Action.CART_TRANSITION,AuditValues.Resource.CART,before.id(),correlation,reason,Map.of("state",before.state(),"version",before.version()),Map.of("state",state,"version",before.version()+1),null);TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCommit(){metrics.counter("nigson.cart.commands","operation","TRANSITION").increment();}});UUID party=jdbc.queryForObject("SELECT party_id FROM commerce.cart WHERE id=?",UUID.class,before.id());return carts.find(party,before.id(),false);}
 public CartValues.Cart pending(UUID party,UUID id,long expected,UUID quote,String hash,UUID orderId,UUID correlation){transaction();var c=carts.find(party,id,true);if(c.version()!=expected)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);if(!c.state().equals("ACTIVE"))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);if(hash==null||!hash.matches("[a-f0-9]{64}"))throw ApiValues.invalid();if(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.checkout_quote WHERE id=? AND cart_id=? AND cart_version=? AND quote_hash=? AND expires_at>?)",Boolean.class,quote,id,expected,hash,java.sql.Timestamp.from(clock.instant()))))throw new Problem.Failure(ProblemCode.CHECKOUT_REPRICE_REQUIRED);var o=order(orderId,false);if(!id.equals(o.get("cart_id"))||!party.equals(o.get("party_id"))||!c.marketId().equals(o.get("market_id"))||!Objects.equals(c.organizationId(),o.get("organization_id"))||!o.get("status").equals("PENDING")||!Set.of("UNPAID","PENDING").contains(o.get("payment_status")))throw CartValues.rule();return change(c,"CHECKOUT_PENDING",null,correlation,AuditValues.Reason.OPERATOR_REQUEST);}
 public CartValues.Cart converted(UUID orderId,UUID correlation){transaction();var o=order(orderId,true);var c=context(o);if(!Set.of("PAID","PARTIALLY_REFUNDED","REFUNDED").contains(o.get("payment_status")))throw CartValues.rule();if(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.payment_attempt a JOIN commerce.payment_transaction t ON t.attempt_id=a.id WHERE a.order_id=? AND a.state='SUCCEEDED' AND a.verified_at IS NOT NULL AND a.currency_code=? AND t.currency_code=a.currency_code AND a.expected_amount=? AND t.settled_amount=a.expected_amount AND t.provider_mode=a.provider_mode AND t.provider_status='success')",Boolean.class,orderId,o.get("currency_code"),o.get("grand_total"))))throw CartValues.rule();if(c.state().equals("CONVERTED")){if(!orderId.equals(jdbc.queryForObject("SELECT converted_order_id FROM commerce.cart WHERE id=?",UUID.class,c.id())))throw CartValues.rule();return c;}if(!Set.of("CHECKOUT_PENDING","EXPIRED").contains(c.state()))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);return change(c,"CONVERTED",orderId,correlation,AuditValues.Reason.VERIFIED_PROVIDER);}
 public CartValues.Cart expired(UUID orderId,UUID correlation){transaction();var o=order(orderId,true);var c=context(o);if(!o.get("status").equals("CANCELLED")||!Set.of("UNPAID","FAILED").contains(o.get("payment_status")))throw CartValues.rule();if(Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.payment_attempt a WHERE a.order_id=? AND (a.state NOT IN ('FAILED','CANCELLED') OR a.verified_at IS NULL)) OR EXISTS(SELECT 1 FROM commerce.payment_transaction t JOIN commerce.payment_attempt a ON a.id=t.attempt_id WHERE a.order_id=?) OR EXISTS(SELECT 1 FROM commerce.inventory_reservation WHERE order_id=? AND status IN ('RESERVED','ALLOCATED'))",Boolean.class,orderId,orderId,orderId)))throw CartValues.rule();if(c.state().equals("EXPIRED"))return c;if(!c.state().equals("CHECKOUT_PENDING"))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);return change(c,"EXPIRED",null,correlation,AuditValues.Reason.RECONCILIATION);}
 public boolean recoveryEligible(UUID party,UUID id){transaction();var c=carts.find(party,id,true);return c.state().equals("ACTIVE")&&!c.lines().isEmpty()&&!c.lastActivityAt().isAfter(clock.instant().minus(Duration.ofHours(24)))&&!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.sales_order WHERE cart_id=? OR (party_id=? AND organization_id IS NOT DISTINCT FROM ?::uuid AND market_id=? AND payment_status IN ('PAID','PARTIALLY_REFUNDED','REFUNDED') AND created_at>=?))",Boolean.class,id,party,c.organizationId(),c.marketId(),java.sql.Timestamp.from(c.lastActivityAt())));}
}
